mapper.select:
select p.post_no, title, p.member_uuid, name, post_like, reg_date from post p join member m on p.member_uuid = m.member_uuid join post_brand pb on p.post_no = pb.post_no where brand_id in
#{brand_id}
group by p.post_no having count(distinct brand_id)=1

select count(*) from post p join post_brand pb on p.post_no = pb.post_no where brand_id in
#{brand_id}
group by p.post_no having count(distinct brand_id)=1
